mkdir -p /Users/edge/Developer/betterdesk-redesign/docs/quality-v2/screenshots/baseline; cat > $TMPDIR/shot.mjs <<'EOF'
import { chromium } from '@playwright/test';
const out='/Users/edge/Developer/betterdesk-redesign/docs/quality-v2/screenshots/baseline/';
const b=await chromium.launch();
const W=[[320,844],[390,844],[768,900],[1440,900],[1920,900]];
const wait=p=>p.waitForTimeout(1200);
for(const [w,h] of W){
  const ctx=await b.newContext({viewport:{width:w,height:h}});
  const p=await ctx.newPage();
  await p.goto('http://localhost:3917/',{waitUntil:'load'});await wait(p);
  await p.screenshot({path:out+`home-${w}-top.png`});
  const H=await p.evaluate(()=>document.documentElement.scrollHeight);
  await p.evaluate(y=>window.scrollTo(0,y),Math.max(0,H/2-h/2));await wait(p);
  await p.screenshot({path:out+`home-${w}-mid.png`});
  await p.evaluate(()=>window.scrollTo(0,document.documentElement.scrollHeight));await wait(p);
  await p.screenshot({path:out+`home-${w}-bottom.png`});
  if(w===1440||w===390){
    // scroll through to trigger reveals
    for(let y=0;y<H;y+=h/2){await p.evaluate(y=>window.scrollTo(0,y),y);await p.waitForTimeout(150);}
    await p.evaluate(()=>window.scrollTo(0,0));await wait(p);
    await p.screenshot({path:out+`home-${w}-full.png`,fullPage:true});
    console.log(w,'height',H);
    for(const r of ['platform','how-it-works','demo','pricing','solutions','roi','contact']){
      await p.goto('http://localhost:3917/'+r,{waitUntil:'load'});await wait(p);
      await p.screenshot({path:out+`${r}-${w}-top.png`});
    }
  }
  await ctx.close();
}
await b.close();
EOF
cd /Users/edge/Developer/betterdesk-redesign && cp $TMPDIR/shot.mjs ./.shot-tmp.mjs && PLAYWRIGHT_BROWSERS_PATH=$PWD/.pw-browsers node .shot-tmp.mjs; rm -f .shot-tmp.mjs; ls docs/quality-v2/screenshots/baseline | wc -l

